#!/usr/bin/env node
/**
 * Installs this package's Mendix JavaScript actions into a Mendix project.
 *
 *   npx react-native-airfob install-mendix ./MyMendixApp
 *   npx react-native-airfob check-mendix   ./MyMendixApp     # CI drift gate
 *   npx react-native-airfob list-mendix
 *
 * Why this exists rather than "copy these files":
 *
 *   Mendix rejects semver ranges in a native-dependency sidecar — an exact
 *   version is required — and Studio Pro refuses to package the app when two
 *   components declare different versions of the same dependency. With one
 *   sidecar per action that is a build break waiting to happen. Writing the
 *   sidecars from the package's own version makes drift impossible rather than
 *   merely detectable.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const PKG = require("../package.json");
const PKG_ROOT = path.resolve(__dirname, "..");
const ACTIONS_DIR = path.join(PKG_ROOT, "mendix", "actions");
const MAPPINGS_DIR = path.join(PKG_ROOT, "mendix", "mappings");

const DEFAULT_MODULE = "Airfob";
const MARKER = "@airfob-generated";

/* ------------------------------------------------------------------ utils -- */

// Colour only when a human is watching. CI logs and piped output stay clean.
const COLOUR = process.stdout.isTTY && !process.env.NO_COLOR;
const wrap = code => s => (COLOUR ? `[${code}m${s}[0m` : s);
const c = {
  dim: wrap(2),
  green: wrap(32),
  yellow: wrap(33),
  red: wrap(31),
  bold: wrap(1)
};

function die(message) {
  console.error(c.red("error: ") + message);
  process.exit(1);
}

function actionNames() {
  return fs
    .readdirSync(ACTIONS_DIR)
    .filter(f => f.endsWith(".js"))
    .map(f => f.replace(/\.js$/, ""))
    .sort();
}

function sidecarFor(version) {
  return JSON.stringify({ nativeDependencies: { [PKG.name]: version } }, null, 4) + "\n";
}

/**
 * A Mendix project root holds a .mpr next to a javascriptsource directory.
 * Accepting the wrong directory silently would scatter files somewhere useless,
 * so this is strict and says what it looked for.
 */
function resolveProject(target) {
  if (!target) die("a Mendix project path is required");

  const root = path.resolve(target);
  if (!fs.existsSync(root)) die(`no such directory: ${root}`);
  if (!fs.statSync(root).isDirectory()) die(`not a directory: ${root}`);

  const hasMpr = fs.readdirSync(root).some(f => f.endsWith(".mpr"));
  const hasJsSource = fs.existsSync(path.join(root, "javascriptsource"));

  if (!hasMpr && !hasJsSource) {
    die(
      `${root} does not look like a Mendix project\n` +
        "       expected a .mpr file or a javascriptsource/ directory"
    );
  }

  return root;
}

/* --------------------------------------------------------------- install -- */

function install(target, options) {
  const root = resolveProject(target);
  const moduleName = options.module || DEFAULT_MODULE;
  const dest = path.join(root, "javascriptsource", moduleName, "actions");

  fs.mkdirSync(dest, { recursive: true });

  console.log(`${c.bold(PKG.name)}@${PKG.version} -> ${root}`);
  console.log(c.dim(`  module: ${moduleName}`));
  console.log("");

  let written = 0;
  let skipped = 0;
  let unchanged = 0;

  for (const name of actionNames()) {
    const sourceJs = path.join(ACTIONS_DIR, `${name}.js`);
    const targetJs = path.join(dest, `${name}.js`);
    const targetJson = path.join(dest, `${name}.json`);
    const contents = fs.readFileSync(sourceJs, "utf8");

    if (fs.existsSync(targetJs)) {
      const existing = fs.readFileSync(targetJs, "utf8");

      // Never clobber a file a human wrote. Our own output carries a marker;
      // anything without it is treated as hand-authored and left alone.
      if (!existing.includes(MARKER) && !options.force) {
        console.log(`  ${c.yellow("skip")}    ${name}.js ${c.dim("(not generated by us; --force to overwrite)")}`);
        skipped += 1;
        continue;
      }

      if (existing === contents && fs.existsSync(targetJson) &&
          fs.readFileSync(targetJson, "utf8") === sidecarFor(PKG.version)) {
        console.log(`  ${c.dim("ok")}      ${name}`);
        unchanged += 1;
        continue;
      }
    }

    fs.writeFileSync(targetJs, contents);
    fs.writeFileSync(targetJson, sidecarFor(PKG.version));
    console.log(`  ${c.green("write")}   ${name}.js + .json`);
    written += 1;
  }

  // The mapping samples are not part of the Mendix project structure — they are
  // pasted into the Import Mapping wizard — so they land in a sibling folder
  // rather than inside javascriptsource.
  const mappingDest = path.join(root, "airfob-mappings");
  fs.mkdirSync(mappingDest, { recursive: true });
  for (const f of fs.readdirSync(MAPPINGS_DIR)) {
    fs.copyFileSync(path.join(MAPPINGS_DIR, f), path.join(mappingDest, f));
  }

  console.log("");
  console.log(
    `  ${written} written, ${unchanged} unchanged` + (skipped ? `, ${c.yellow(skipped + " skipped")}` : "")
  );
  console.log("");
  console.log(c.bold("next, in Studio Pro"));
  console.log(`  1. Refresh the project (F4) so it picks up ${moduleName}/actions`);
  console.log("  2. For each file in airfob-mappings/: right-click the module ->");
  console.log("     Add other -> Import Mapping -> Use a JSON structure -> paste");
  console.log("     That generates the entities; you do not build them by hand.");
  console.log("  3. Call AirfobBoot from the home page on-load nanoflow.");
  console.log("");
  console.log(c.dim("  Make It Native cannot load custom native code — the package"));
  console.log(c.dim("  falls back to its mock there and reports sdkReady: false."));
}

/* ----------------------------------------------------------------- check -- */

/** CI gate: fail if any installed sidecar has drifted from the package version. */
function check(target, options) {
  const root = resolveProject(target);
  const moduleName = options.module || DEFAULT_MODULE;
  const dest = path.join(root, "javascriptsource", moduleName, "actions");

  if (!fs.existsSync(dest)) {
    die(`not installed: ${dest}\n       run: npx ${PKG.name} install-mendix ${target}`);
  }

  const expected = sidecarFor(PKG.version);
  const problems = [];

  for (const name of actionNames()) {
    const targetJs = path.join(dest, `${name}.js`);
    const targetJson = path.join(dest, `${name}.json`);

    if (!fs.existsSync(targetJs)) {
      problems.push(`${name}.js is missing`);
      continue;
    }
    if (!fs.existsSync(targetJson)) {
      problems.push(`${name}.json is missing`);
      continue;
    }
    if (fs.readFileSync(targetJson, "utf8") !== expected) {
      const found = JSON.parse(fs.readFileSync(targetJson, "utf8"));
      problems.push(`${name}.json pins ${found.nativeDependencies[PKG.name]}, expected ${PKG.version}`);
    }
    if (fs.readFileSync(targetJs, "utf8") !== fs.readFileSync(path.join(ACTIONS_DIR, `${name}.js`), "utf8")) {
      problems.push(`${name}.js differs from the packaged source`);
    }
  }

  if (problems.length) {
    console.error(c.red(`${problems.length} problem(s):`));
    problems.forEach(p => console.error(`  - ${p}`));
    console.error("");
    console.error(`Run: npx ${PKG.name} install-mendix ${target}`);
    process.exit(1);
  }

  console.log(c.green(`ok`) + ` — ${actionNames().length} actions at ${PKG.version}`);
}

/* ------------------------------------------------------------------ list -- */

function list() {
  console.log(`${c.bold(PKG.name)}@${PKG.version}`);
  console.log("");
  console.log(c.bold("actions"));
  actionNames().forEach(n => console.log(`  ${n}`));
  console.log("");
  console.log(c.bold("import-mapping samples"));
  fs.readdirSync(MAPPINGS_DIR).forEach(f => console.log(`  ${f}`));
}

/* ------------------------------------------------------------------ main -- */

function usage() {
  console.log(`${PKG.name} ${PKG.version}

  npx ${PKG.name} install-mendix <project> [--module Airfob] [--force]
  npx ${PKG.name} check-mendix   <project> [--module Airfob]
  npx ${PKG.name} list-mendix

  --module  Mendix module name (default: ${DEFAULT_MODULE})
  --force   overwrite action files not generated by this tool
`);
}

function main(argv) {
  const args = argv.slice(2);
  const command = args[0];
  const positional = args.slice(1).filter(a => !a.startsWith("--"));
  const options = {
    force: args.includes("--force"),
    module: (() => {
      const i = args.indexOf("--module");
      return i >= 0 ? args[i + 1] : null;
    })()
  };

  switch (command) {
    case "install-mendix":
      return install(positional[0], options);
    case "check-mendix":
      return check(positional[0], options);
    case "list-mendix":
      return list();
    case "--help":
    case "-h":
    case undefined:
      return usage();
    default:
      console.error(c.red(`unknown command: ${command}`));
      usage();
      process.exit(1);
  }
}

main(process.argv);
